  'This course introduces education as a historical, philosophical, sociological, political, legal, ethical, and professional field. Students examine the purposes of schooling, U.S. education history, learning and development, curriculum and assessment, governance and finance, law and policy, equity and opportunity, teacher professionalism, comparative education, and current reform debates. The course prepares future educators to connect classroom practice with the broader systems and values that shape schooling.',
  $foedjson${"slug": "foundations-of-education", "title": "Foundations of Education", "description": "This course introduces education as a historical, philosophical, sociological, political, legal, ethical, and professional field. Students examine the purposes of schooling, U.S. education history, learning and development, curriculum and assessment, governance and finance, law and policy, equity and opportunity, teacher professionalism, comparative education, and current reform debates. The course prepares future educators to connect classroom practice with the broader systems and values that shape schooling.", "topics": [{"id": "9116cfe0-fb5d-419b-bb30-7b4a6a6b4a45", "type": "topic", "title": "Education as a Field: Purposes, Institutions, and Public Good", "description": "This opening unit frames education as a public, moral, cultural, and political enterprise. Students begin by asking what schools are for and how different answers shape teaching, policy, curriculum, assessment, and reform.", "children": [{"id": "b089f51f-496a-4c8b-b3dc-bc0dcb633b91", "type": "subtopic", "title": "Purposes of education", "children": [{"id": "25ee857b-bf96-4a94-8ce9-c6c7ef20900e", "type": "concept", "title": "Democratic citizenship and civic life"}, {"id": "746ce6fe-77fa-49d3-b7b3-a6915fd23e04", "type": "concept", "title": "Economic preparation and workforce development"}, {"id": "6a74cfe3-ea12-4fc6-9864-18329c63be84", "type": "concept", "title": "Personal growth, cultural transmission, and social transformation"}], "description": "Students compare major claims about why schooling matters and what it should accomplish."}, {"id": "05c71d5a-3076-468c-b754-e9c3dc0feccd", "type": "subtopic", "title": "Schools as institutions", "children": [{"id": "adb21ac1-cbc5-40f9-935e-27fc78bba874", "type": "concept", "title": "Public, private, charter, magnet, and alternative schools"}, {"id": "d9844b48-8558-45d9-ad80-0bafb84be1d6", "type": "concept", "title": "Districts, boards, states, and federal roles"}, {"id": "1d8478ac-704c-40bc-975c-b8dce36fdef4", "type": "concept", "title": "School culture, routines, and hidden curriculum"}], "description": "Students learn that schools are complex organizations shaped by history, policy, families, communities, and professional norms."}, {"id": "37cc0f14-7930-4bae-a833-7082b29d8238", "type": "subtopic", "title": "Education as a public good", "children": [{"id": "60ac7326-0cd9-426c-a79b-ae7f272011ba", "type": "concept", "title": "Access and opportunity"}, {"id": "e834da84-cd57-4199-9a4f-3f3f6f9d6b8c", "type": "concept", "title": "Common schooling and pluralism"}, {"id": "c3361f89-6162-499e-b5fa-7877bfeb83c4", "type": "concept", "title": "Public trust, accountability, and legitimacy"}], "description": "Students examine tensions between individual benefit and collective responsibility."}]}, {"id": "c4ee6436-7494-4b1f-b93e-7a8a495581f2", "type": "topic", "title": "History of American Education", "description": "History helps educators see that today's schools are built from earlier choices, conflicts, exclusions, and reforms. This unit gives students a long view of schooling and the profession.", "children": [{"id": "6b76dff5-5602-44ae-b1f8-5eddc3f5928d", "type": "subtopic", "title": "Early schooling and common-school reform", "children": [{"id": "9bba809f-8ecc-401c-9e1c-964c403b76c0", "type": "concept", "title": "Colonial and early republic education"}, {"id": "9a190dbe-81ef-4038-b6b8-e9b92a65d603", "type": "concept", "title": "Horace Mann and the common-school movement"}, {"id": "0d5de12d-7b08-4cb7-a363-47bfa5329947", "type": "concept", "title": "Normal schools and teacher preparation"}], "description": "Students learn how early U.S. schooling developed from local, religious, civic, and political aims."}, {"id": "b6622ba1-1d6d-4c09-a7e6-bf35df3085c9", "type": "subtopic", "title": "Expansion, segregation, and access", "children": [{"id": "3d9b7786-5d98-49a4-9ab0-9a05114939f8", "type": "concept", "title": "Native American boarding schools"}, {"id": "d66dc52f-0438-466a-83bc-be45c4581a1f", "type": "concept", "title": "Segregation, Brown v. Board, and desegregation"}, {"id": "c3c58fdd-d2d5-4c3e-9949-e62889d03029", "type": "concept", "title": "Women, immigrants, multilingual learners, and disability rights"}], "description": "Students examine how access to schooling expanded unevenly across race, class, gender, language, disability, and geography."}, {"id": "6f2f02ad-b6a1-48da-9e69-0f34c0a3483c", "type": "subtopic", "title": "Modern reform eras", "children": [{"id": "d9b2559b-0824-42b3-8744-c8d800d7fc14", "type": "concept", "title": "Progressive education and vocational education"}, {"id": "8f285a0f-f132-413a-8e28-588c367b3390", "type": "concept", "title": "A Nation at Risk, standards, and accountability"}, {"id": "b8548090-75e4-43b7-8458-16d7c8937360", "type": "concept", "title": "Choice, charter schools, testing, and teacher evaluation"}], "description": "Students trace reform waves that still shape contemporary debates."}]}, {"id": "56a6da4d-ce26-410c-8299-20cd206d90b8", "type": "topic", "title": "Philosophical Foundations of Education", "description": "Every teaching decision rests on assumptions about knowledge, learners, authority, and society. This unit helps students identify and defend their own educational philosophy.", "children": [{"id": "d798aab9-67ab-4401-a124-2f7e0473870f", "type": "subtopic", "title": "Major philosophies of education", "children": [{"id": "2040f5a5-057b-4e6c-bbb3-7b429218dbe5", "type": "concept", "title": "Essentialism, perennialism, progressivism, and reconstructionism"}, {"id": "be458949-354a-499d-912a-17b28e5efa33", "type": "concept", "title": "Pragmatism, constructivism, and humanism"}, {"id": "a3eb9d04-16cf-4df8-8479-28a39c5b7be3", "type": "concept", "title": "Critical pedagogy and liberatory education"}], "description": "Students compare philosophical traditions that shape schooling and teaching."}, {"id": "1fa42e71-97c2-4784-91bd-e221c8366cc8", "type": "subtopic", "title": "Knowledge, curriculum, and authority", "children": [{"id": "a446d6ff-5f2a-49a5-87ca-5ad05207775c", "type": "concept", "title": "Canon, standards, and disciplinary knowledge"}, {"id": "9c671f0d-2716-4e39-9cb8-28bee9e5c9a1", "type": "concept", "title": "Student interest and inquiry"}, {"id": "f9dbb546-5b98-4635-8657-ce2499ad5e22", "type": "concept", "title": "Hidden, null, and enacted curriculum"}], "description": "Students ask who decides what knowledge counts and how curriculum reflects values."}, {"id": "a6fd73e1-42b3-444c-bf47-491b62906349", "type": "subtopic", "title": "Ethics of teaching", "children": [{"id": "0c91a0cb-4212-4cce-90b8-150476edf923", "type": "concept", "title": "Care, fairness, and respect"}, {"id": "57ef64a5-8194-46a1-9b99-a8b853b6984d", "type": "concept", "title": "Professional boundaries and judgment"}, {"id": "0f2a35ec-c396-4f12-93dc-983c64f3e545", "type": "concept", "title": "Moral dilemmas in classroom practice"}], "description": "Students study teaching as a relational profession with ethical obligations."}]}, {"id": "1a1f8b46-c7cb-49bb-a329-731dbc75cdb5", "type": "topic", "title": "Sociology of Schools and Social Context", "description": "Schools are not isolated from society. This unit helps students understand how family, neighborhood, culture, peers, policy, and institutions shape educational experience.", "children": [{"id": "afd95cf3-1480-4c3f-801f-3b6ed92db803", "type": "subtopic", "title": "Schools and socialization", "children": [{"id": "2a63b847-f7d2-442b-98c8-9b3e496374de", "type": "concept", "title": "Peer culture and school climate"}, {"id": "5ab5285f-2395-4613-bbbc-1b7c26cc9f01", "type": "concept", "title": "Rituals, routines, and hidden curriculum"}, {"id": "de9a0f02-d57c-4f1e-bdb9-780612d28226", "type": "concept", "title": "Tracking, labeling, and expectation effects"}], "description": "Students learn how schools transmit norms, identities, expectations, and civic habits."}, {"id": "4e1e1f1e-5f5f-4