aps"}, {"id": "62a20894-4241-4df3-8e50-cc593161ea0c", "type": "concept", "title": "Intersectionality and identity-safe environments"}, {"id": "4bd2b221-9c43-4b0a-9a26-cc2f6a56bb86", "type": "concept", "title": "Equity audits and disproportionality"}], "description": "Students learn to distinguish equal treatment from equitable opportunity."}, {"id": "9c892b4a-4893-42b6-942c-3a0b763c0bc7", "type": "subtopic", "title": "Culturally responsive and sustaining pedagogy", "children": [{"id": "50983b28-3023-4e34-aa53-20325cf759d6", "type": "concept", "title": "Culturally relevant pedagogy"}, {"id": "4ebd7e4d-9b92-4d32-a7a6-f9d28799702a", "type": "concept", "title": "Culturally responsive teaching"}, {"id": "91be8001-61c3-459e-8448-f815955da45b", "type": "concept", "title": "Culturally sustaining pedagogy and funds of knowledge"}], "description": "Students learn instructional approaches that affirm identity while supporting rigorous learning."}, {"id": "73a8f3be-a1b1-41d8-a59d-e1ad87e0a582", "type": "subtopic", "title": "Inclusive and anti-oppressive practice", "children": [{"id": "71d03eb5-e236-44eb-a3af-35750164a612", "type": "concept", "title": "Anti-bias and anti-racist teaching"}, {"id": "3050220f-31c8-41a2-ba38-a02fcc966534", "type": "concept", "title": "Multilingual learners and language assets"}, {"id": "3ccdf627-911b-4abd-aa3d-9f512e4ff929", "type": "concept", "title": "Disability justice, UDL, and accessibility"}], "description": "Students connect equity to classroom routines, curriculum, and family partnership."}]}, {"id": "eae7e6d3-301b-4cc1-8297-b873af9f8271", "type": "topic", "title": "Teacher Professionalism, Identity, and Reflective Practice", "description": "Teaching is intellectual, relational, ethical, and collaborative work. This unit helps students imagine themselves as reflective professionals inside a larger field.", "children": [{"id": "b5ef3553-1494-4b56-98d9-53a7a72ec4ec", "type": "subtopic", "title": "Teacher identity and professionalism", "children": [{"id": "e96ebc9d-e9f9-4ec5-a0dc-3ffba1610ef8", "type": "concept", "title": "Professional standards and dispositions"}, {"id": "de3ae490-8b12-4108-9111-f215a173133a", "type": "concept", "title": "Teacher autonomy and accountability"}, {"id": "a7ed5828-07ed-476e-9120-fc8a81f3ef64", "type": "concept", "title": "Role models, identity, and commitments"}], "description": "Students examine what it means to become a teacher."}, {"id": "03625161-64ad-4af4-ba53-45b605b49fb3", "type": "subtopic", "title": "Collaboration and reflective inquiry", "children": [{"id": "1299366b-d00c-45d8-84e9-cc5d5198806a", "type": "concept", "title": "Professional learning communities"}, {"id": "b3e56ac4-bbb9-44fd-9c9d-b78231f24836", "type": "concept", "title": "Coaching, observation, and feedback"}, {"id": "3bbc296a-7794-4fe7-8a41-47e26343373f", "type": "concept", "title": "Reflective journals and inquiry cycles"}], "description": "Students learn habits that support growth across a teaching career."}, {"id": "8b091db0-9659-4875-936c-afa8e56087dc", "type": "subtopic", "title": "Teacher wellbeing and sustainability", "children": [{"id": "d9b9392b-30fd-4c2b-acd4-71892b0248aa", "type": "concept", "title": "Workload, boundaries, and emotional labor"}, {"id": "1702d3db-d8ed-4c04-84ed-9064491a3187", "type": "concept", "title": "Burnout, resilience, and support systems"}, {"id": "ee0b5b64-f7b3-4430-b051-951e3b2e9788", "type": "concept", "title": "Collective efficacy and professional community"}], "description": "Students learn to treat educator wellbeing as a professional and organizational issue."}]}, {"id": "d146c1a4-120a-47a8-b4cc-bb18cb169320", "type": "topic", "title": "Comparative and International Perspectives", "description": "Comparative education helps students see that familiar school structures are choices, not inevitabilities. This unit broadens perspective while avoiding simplistic rankings and policy copying.", "children": [{"id": "562f8f08-f0b9-46da-8f4e-8612c52d8bcd", "type": "subtopic", "title": "Why compare education systems", "children": [{"id": "f7f80b72-0d99-4e15-ba2a-1f3c4b4a225d", "type": "concept", "title": "Policy borrowing and context"}, {"id": "6d776a17-1369-4219-90e1-c5f007cc27d0", "type": "concept", "title": "Culture, governance, and history"}, {"id": "14f3b3c4-4dc2-423c-87af-b1b312cbef34", "type": "concept", "title": "Limits of international rankings"}], "description": "Students learn what comparison can and cannot teach."}, {"id": "cf08115a-3dc9-4bab-a14e-e8d62b7b9d7b", "type": "subtopic", "title": "Global indicators and debates", "children": [{"id": "940b7c2a-7085-4bd7-ac0e-7d36f7f925e4", "type": "concept", "title": "PISA, TIMSS, and international assessments"}, {"id": "b4437469-139f-41df-9730-c7045b304ed8", "type": "concept", "title": "Access, literacy, gender, and development"}, {"id": "71133e8e-d443-4692-b241-33d1221f7107", "type": "concept", "title": "Human rights and education"}], "description": "Students examine common measures and their interpretation."}, {"id": "71a555a7-c445-418a-9249-796651532823", "type": "subtopic", "title": "Lessons for local practice", "children": [{"id": "afdc7e5d-66b5-48e3-bf2d-035cad8af3c1", "type": "concept", "title": "Teacher preparation and professional status"}, {"id": "d0f340e1-28b0-42dd-8ef0-a0509b5c281e", "type": "concept", "title": "Curriculum breadth and assessment culture"}, {"id": "5a55fa88-74ac-44bf-9e18-ea11ca3eab00", "type": "concept", "title": "Equity, inclusion, and multilingual education"}], "description": "Students connect global comparison to reflective professional judgment."}]}, {"id": "a4ee60ee-1961-4c74-b1b9-457812810054", "type": "topic", "title": "Current Debates, Reform, and the Future of Education", "description": "The capstone unit asks students to use history, philosophy, sociology, learning science, law, policy, and equity to analyze live debates in education.", "children": [{"id": "6dcf8622-aaf5-415d-9493-d4be112bee14", "type": "subtopic", "title": "Major reform debates", "children": [{"id": "7f4fe617-1195-4bb9-b6fe-7dd6822489b9", "type": "concept", "title": "School choice, charters, vouchers, and privatization"}, {"id": "82bf5f54-9cc8-4507-9948-c6dc688c07f1", "type": "concept", "title": "Testing and accountability reform"}, {"id": "658e9567-0a17-4f42-b851-e9f674c0ae43", "type": "concept", "title": "Teacher workforce, pay, preparation, and retention"}], "description": "Students learn to evaluate reforms by asking who benefits, who decides, and what evidence matters."}, {"id": "715c48b1-2d7c-4cf3-b372-1d826b01e5a8", "type": "subtopic", "title": "Technology and the future of learning", "children": [{"id": "a88dcbfd-cd78-4d84-b455-9f3320997f8d", "type": "concept", "title": "AI, tutoring systems, and adaptive learning"}, {"id": "bcd6ed27-671b-42b4-81ee-99efe3246d22", "type": "concept", "title": "Privacy, surveillance, and data ethics"}, {"id": "fb71f7f1-483a-478b-a770-1e8d25e2048f", "type": "concept", "title": "Digital equity and access"}], "description": "Students examine opportunities and risks in educational technology."}, {"id": "3c30b98b-416f-4815-bfcc-12ceffa29c7c", "type": "subtopic", "title": "Professional synthesis", "children": [{"id": "4528d945-5e42-4bf8-bfbf-66ea1a4d8be4", "type": "concept", "title": "Final philosophy revision"}, {"id": "97fa6435-1208-4aa7-851e-e18aa73ca29a", "type": "concept", "title": "Evidence-based commitments"}, {"id": "baa906f4-4ecf-44d6-891a-70712c3a4f9c", "type": "concept", "title": "Action plan for fieldwork and future learning"}], "description": "Students articulate a grounded philosophy of education and teaching."}]}], "dbBacked": true}$foedjson$::jsonb,
