update public.learning_paths
set
  title = 'Foundations of Education',
  goal = 'Foundations of Education',
  summary = 'This course introduces education as a historical, philosophical, sociological, political, legal, ethical, and professional field. Students examine the purposes of schooling, U.S. education history, learning and development, curriculum and assessment, governance and finance, law and policy, equity and opportunity, teacher professionalism, comparative education, and current reform debates. The course prepares future educators to connect classroom practice with the broader systems and values that shape schooling.',
  data = $foedjson${"slug": "foundations-of-education", "title": "Foundations of Education", "description": "This course introduces education as a historical, philosophical, sociological, political, legal, ethical, and professional field. Students examine the purposes of schooling, U.S. education history, learning and development, curriculum and assessment, governance and finance, law and policy, equity and opportunity, teacher professionalism, comparative education, and current reform debates. The course prepares future educators to connect classroom practice with the broader systems and values that shape schooling.", "topics": [{"id": "9116cfe0-fb5d-419b-bb30-7b4a6a6b4a45", "type": "topic", "title": "Education as a Field: Purposes, Institutions, and Public Good", "description": "This opening unit frames education as a public, moral, cultural, and political enterprise. Students begin by asking what schools are for and how different answers shape teaching, policy, curriculum, assessment, and reform.", "children": [{"id": "b089f51f-496a-4c8b-b3dc-bc0dcb633b91", "type": "subtopic", "title": "Purposes of education", "children": [{"id": "25ee857b-bf96-4a94-8ce9-c6c7ef20900e", "type": "concept", "title": "Democratic citizenship and civic life"}, {"id": "746ce6fe-77fa-49d3-b7b3-a6915fd23e04", "type": "concept", "title": "Economic preparation and workforce development"}, {"id": "6a74cfe3-ea12-4fc6-9864-18329c63be84", "type": "concept", "title": "Personal growth, cultural transmission, and social transformation"}], "description": "Students compare major claims about why schooling matters and what it should accomplish."}, {"id": "05c71d5a-3076-468c-b754-e9c3dc0feccd", "type": "subtopic", "title": "Schools as institutions", "children": [{"id": "adb21ac1-cbc5-40f9-935e-27fc78bba874", "type": "concept", "title": "Public, private, charter, magnet, and alternative schools"}, {"id": "d9844b48-8558-45d9-ad80-0bafb84be1d6", "type": "concept", "title": "Districts, boards, states, and federal roles"}, {"id": "1d8478ac-704c-40bc-975c-b8dce36fdef4", "type": "concept", "title": "School culture, routines, and hidden curriculum"}], "description": "Students learn that schools are complex organizations shaped by history, policy, families, communities, and professional norms."}, {"id": "37cc0f14-7930-4bae-a833-7082b29d8238", "type": "subtopic", "title": "Education as a public good", "children": [{"id": "60ac7326-0cd9-426c-a79b-ae7f272011ba", "type": "concept", "title": "Access and opportunity"}, {"id": "e834da84-cd57-4199-9a4f-3f3f6f9d6b8c", "type": "concept", "title": "Common schooling and pluralism"}, {"id": "c3361f89-6162-499e-b5fa-7877bfeb83c4", "type": "concept", "title": "Public trust, accountability, and legitimacy"}], "description": "Students examine tensions between individual benefit and collective responsibility."}]}, {"id": "c4ee6436-7494-4b1f-b93e-7a8a495581f2", "type": "topic", "title": "History of American Education", "description": "History helps educators see that today's schools are built from earlier choices, conflicts, exclusions, and reforms. This unit gives students a long view of schooling and the profession.", "children": [{"id": "6b76dff5-5602-44ae-b1f8-5eddc3f5928d", "type": "subtopic", "title": "Early schooling and common-school reform", "children": [{"id": "9bba809f-8ecc-401c-9e1c-964c403b76c0", "type": "concept", "title": "Colonial and early republic education"}, {"id": "9a190dbe-81ef-4038-b6b8-e9b92a65d603", "type": "concept", "title": "Horace Mann and the common-school movement"}, {"id": "0d5de12d-7b08-4cb7-a363-47bfa5329947", "type": "concept", "title": "Normal schools and teacher preparation"}], "description": "Students learn how early U.S. schooling developed from local, religious, civic, and political aims."}, {"id": "b6622ba1-1d6d-4c09-a7e6-bf35df3085c9", "type": "subtopic", "title": "Expansion, segregation, and access", "children": [{"id": "3d9b7786-5d98-49a4-9ab0-9a05114939f8", "type": "concept", "title": "Native American boarding schools"}, {"id": "d66dc52f-0438-466a-83bc-be45c4581a1f", "type": "concept", "title": "Segregation, Brown v. Board, and desegregation"}, {"id": "c3c58fdd-d2d5-4c3e-9949-e62889d03029", "type": "concept", "title": "Women, immigrants, multilingual learners, and disability rights"}], "description": "Students examine how access to schooling expanded unevenly across race, class, gender, language, disability, and geography."}, {"id": "6f2f02ad-b6a1-48da-9e69-0f34c0a3483c", "type": "subtopic", "title": "Modern reform eras", "children": [{"id": "d9b2559b-0824-42b3-8744-c8d800d7fc14", "type": "concept", "title": "Progressive education and vocational education"}, {"id": "8f285a0f-f132-413a-8e28-588c367b3390", "type": "concept", "title": "A Nation at Risk, standards, and accountability"}, {"id": "b8548090-75e4-43b7-8458-16d7c8937360", "type": "concept", "title": "Choice, charter schools, testing, and teacher evaluation"}], "description": "Students trace reform waves that still shape contemporary debates."}]}, {"id": "56a6da4d-ce26-410c-8299-20cd206d90b8", "type": "topic", "title": "Philosophical Foundations of Education", "description": "Every teaching decision rests on assumptions about knowledge, learners, authority, and society. This unit helps students identify and defend their own educational philosophy.", "children": [{"id": "d798aab9-67ab-4401-a124-2f7e0473870f", "type": "subtopic", "title": "Major philosophies of education", "children": [{"id": "2040f5a5-057b-4e6c-bbb3-7b429218dbe5", "type": "concept", "title": "Essentialism, perennialism, progressivism, and reconstructionism"}, {"id": "be458949-354a-499d-912a-17b28e5efa33", "type": "concept", "title": "Pragmatism, constructivism, and humanism"}, {"id": "a3eb9d04-16cf-4df8-8479-28a39c5b7be3", "type": "concept", "title": "Critical pedagogy and liberatory education"}], "description": "Students compare philosophical traditions that shape schooling and teaching."}, {"id": "1fa42e71-97c2-4784-91bd-e221c8366cc8", "type": "subtopic", "title": "Knowledge, curriculum, and authority", "children": [{"id": "a446d6ff-5f2a-49a5-87ca-5ad05207775c", "type": "concept", "title": "Canon, standards, and disciplinary knowledge"}, {"id": "9c671f0d-2716-4e39-9cb8-28bee9e5c9a1", "type": "concept", "title": "Student interest and inquiry"}, {"id": "f9dbb546-5b98-4635-8657-ce2499ad5e22", "type": "concept", "title": "Hidden, null, and enacted curriculum"}], "description": "Students ask who decides what knowledge counts and how curriculum reflects values."}, {"id": "a6fd73e1-42b3-444c-bf47-491b62906349", "type": "subtopic", "title": "Ethics of teaching", "children": [{"id": "0c91a0cb-4212-4cce-90b8-150476edf923", "type": "concept", "title": "Care, fairness, and respect"}, {"id": "57ef64a5-8194-46a1-9b99-a8b853b6984d", "type": "concept", "title": "Professional boundaries and judgment"}, {"id": "0f2a35ec-c396-4f12-93dc-983c64f3e545", "type": "concept", "title": "Moral dilemmas in classroom practice"}], "description": "Students study teaching as a relational profession with ethical obligations."}]}, {"id": "1a1f8b46-c7cb-49bb-a329-731dbc75cdb5", "type": "topic", "title": "Sociology of Schools and Social Context", "description": "Schools are not isolated from society. This unit helps students understand how family, neighborhood, culture, peers, policy, and institutions shape educational experience.", "children": [{"id": "afd95cf3-1480-4c3f-801f-3b6ed92db803", "type": "subtopic", "title": "Schools and socialization", "children": [{"id": "2a63b847-f7d2-442b-98c8-9b3e496374de", "type": "concept", "title": "Peer culture and school climate"}, {"id": "5ab5285f-2395-4613-bbbc-1b7c26cc9f01", "type": "concept", "title": "Rituals, routines, and hidden curriculum"}, {"id": "de9a0f02-d57c-4f1e-bdb9-780612d28226", "type": "concept", "title": "Tracking, labeling, and expectation effects"}], "description": "Students learn how schools transmit norms, identities, expectations, and civic habits."}, {"id": "4e1e1f1e-5f5f-4817-920a-93b347d7e36c", "type": "subtopic", "title": "Family and community context", "children": [{"id": "0d86977a-2ef9-4ffc-baa2-dc7752dc18ba", "type": "concept", "title": "Family engagement and funds of knowledge"}, {"id": "819094ae-c0fe-434e-b34e-d581ee7a9535", "type": "concept", "title": "Community assets and local history"}, {"id": "852edbb4-5968-49fc-a901-74f0c5195e27", "type": "concept", "title": "Trust, communication, and partnership"}], "description": "Students examine relationships between schools and the communities they serve."}, {"id": "e4387991-92a6-4b16-b228-1be1810da4ef", "type": "subtopic", "title": "Inequality and opportunity", "children": [{"id": "bc3cb9d3-0df9-46de-b892-70351e5ceb0e", "type": "concept", "title": "Race, class, language, gender, disability, and immigration"}, {"id": "69ef6627-805a-4835-8095-91ffbf1df67e", "type": "concept", "title": "Opportunity gaps and achievement-gap framing"}, {"id": "4479c733-5d80-49b4-ae96-c19c6749d370", "type": "concept", "title": "Discipline, access, resources, and representation"}], "description": "Students learn to analyze educational outcomes through opportunity structures rather than student deficits."}]}, {"id": "2fc84aaf-d7f8-4162-91e5-c68b6c3cf938", "type": "topic", "title": "How People Learn: Learning Sciences and Development", "description": "A foundation course should connect big ideas about schooling to what is known about learners. This unit gives future educators a research-informed view of learning and development.", "children": [{"id": "f184aacb-0440-4967-87bc-a925080b499e", "type": "subtopic", "title": "Major theories of learning", "children": [{"id": "088ce750-183f-425f-9881-111812da5dd7", "type": "concept", "title": "Behaviorism and reinforcement"}, {"id": "d2894730-8a07-4671-823a-6afa34c04e32", "type": "concept", "title": "Cognitive and constructivist theories"}, {"id": "93de32f9-c4a0-45f4-968c-f0f2f587420d", "type": "concept", "title": "Social learning, situated learning, and sociocultural theory"}], "description": "Students compare learning theories as lenses for instructional decisions."}, {"id": "7fa331fb-dac8-4d80-85aa-5b7fe3d0609c", "type": "subtopic", "title": "Development, motivation, and identity", "children": [{"id": "f5cdc4b1-a060-40df-b906-e56685755bf4", "type": "concept", "title": "Child and adolescent development"}, {"id": "2c6a3cad-10a4-4361-b2bb-94dc20577570", "type": "concept", "title": "Self-regulation and metacognition"}, {"id": "6d5b8550-4c7e-4ace-bda7-88ee19a5888e", "type": "concept", "title": "Motivation, identity, and learner agency"}], "description": "Students learn that learning is shaped by development, motivation, belonging, and agency."}, {"id": "1ff71254-3e3d-4fe1-a025-78855d3bf977", "type": "subtopic", "title": "Evidence standards and learner variability", "children": [{"id": "9df3c00c-23de-420c-92d9-426631ced3a8", "type": "concept", "title": "Memory, retrieval practice, spacing, and feedback"}, {"id": "b1c5ad15-c980-4b8b-bdf3-d8612bf978d3", "type": "concept", "title": "Neuroscience myths and evidence quality"}, {"id": "94f68722-d308-4fe1-8108-ad881d664bf5", "type": "concept", "title": "Universal Design for Learning and inclusion"}], "description": "Students learn to evaluate learning-science claims carefully and design for diverse learners."}]}, {"id": "33e20cd8-e646-49a9-87ac-4fd4ddb9b284", "type": "topic", "title": "Curriculum, Standards, and Assessment Foundations", "description": "Curriculum and assessment translate educational aims into daily work. This unit shows how standards, learning goals, tasks, evidence, and feedback connect.", "children": [{"id": "5f85499e-36f1-4e4c-bf1e-0ef3acd3b280", "type": "subtopic", "title": "Curriculum theory and design", "children": [{"id": "38754dc4-838f-46f5-b9fd-c93e69cd3cbb", "type": "concept", "title": "Curriculum models and design traditions"}, {"id": "c79df26d-cfe9-4315-b72e-f57a0a8659ee", "type": "concept", "title": "Standards, competencies, and learning progressions"}, {"id": "f5579dd8-f9f3-4a87-8fcc-26155eb8fe4f", "type": "concept", "title": "Curriculum mapping and coherence"}], "description": "Students learn how curriculum choices encode assumptions about knowledge, learners, and society."}, {"id": "2ef094a2-7f99-43ef-b5c8-6d729b4d28e2", "type": "subtopic", "title": "Backward design and objectives", "children": [{"id": "26dff62d-ab8c-4b21-b56a-62eb54c29ec7", "type": "concept", "title": "Learning objectives and success criteria"}, {"id": "ea2c844d-6bc9-4bbb-991b-1e4859b06736", "type": "concept", "title": "Essential questions and transfer goals"}, {"id": "6c4b54c1-92bf-4751-bcbb-f187c4829ea4", "type": "concept", "title": "Lesson and unit planning"}], "description": "Students learn to plan instruction from desired understanding and evidence."}, {"id": "a4b4e375-0ce2-4365-b4c3-72a97a9cfa39", "type": "subtopic", "title": "Assessment foundations", "children": [{"id": "025e42f0-e33c-4b13-b082-b9348c106816", "type": "concept", "title": "Formative and summative assessment"}, {"id": "d3f39b1f-fa30-4256-9bf9-262698370bf5", "type": "concept", "title": "Rubrics, performance tasks, and portfolios"}, {"id": "26e77922-5cb8-404d-9459-98a8fbd72bd1", "type": "concept", "title": "Grading, reporting, and assessment fairness"}], "description": "Students learn how evidence of learning should guide teaching and reporting."}]}, {"id": "2b201770-35b0-47ab-9763-2d73b0a67332", "type": "topic", "title": "Politics, Governance, and School Finance", "description": "Teachers work inside systems. This unit helps students understand who governs schools, how resources are allocated, and why policy decisions shape classroom realities.", "children": [{"id": "cd68dabe-2da8-4033-a0ed-71efb3f49d8d", "type": "subtopic", "title": "Education governance", "children": [{"id": "a054fe15-9a73-47ab-9c89-46e9659990e3", "type": "concept", "title": "Local school boards and districts"}, {"id": "d03e3a14-fa2f-40d2-ab13-e57a9202d921", "type": "concept", "title": "State departments and legislatures"}, {"id": "e59a896c-1ec5-4b47-b8c9-8050bfd9360e", "type": "concept", "title": "Federal role, courts, and civil-rights enforcement"}], "description": "Students learn the layered structure of U.S. education decision-making."}, {"id": "44d437e2-4ef8-42f9-bc4d-6be0ab045e76", "type": "subtopic", "title": "School finance basics", "children": [{"id": "0eed1a27-98e1-4e3d-abeb-a8055611c888", "type": "concept", "title": "Local property taxes, state aid, and federal categorical funds"}, {"id": "b008e935-0f49-410b-920e-e1cc458db499", "type": "concept", "title": "Equity and adequacy debates"}, {"id": "c8a10b15-7f46-47fc-9204-8c64a4fd6d56", "type": "concept", "title": "Resource allocation, staffing, and facilities"}], "description": "Students learn how funding systems influence opportunity."}, {"id": "05751582-2b8f-4939-b295-2290fff68fd9", "type": "subtopic", "title": "Accountability and policy actors", "children": [{"id": "605001f4-ce8f-42c6-923f-9c20129a9cca", "type": "concept", "title": "Standards and testing accountability"}, {"id": "78c5d918-451c-4d25-b7ce-a724c26f7bdf", "type": "concept", "title": "Unions, advocacy groups, families, and philanthropy"}, {"id": "c4425a1b-4fc3-4d4b-ba50-ccbdeb99950c", "type": "concept", "title": "Policy implementation and unintended consequences"}], "description": "Students learn to analyze policy incentives and stakeholders."}]}, {"id": "058216b5-02ce-45c0-ae2f-0ad40acb5317", "type": "topic", "title": "Education Law, Ethics, and Professional Responsibility", "description": "Educators need enough legal and ethical literacy to act responsibly, protect students, and know when to seek guidance. This unit introduces recurring professional dilemmas.", "children": [{"id": "e7aa638c-5486-455f-be71-eed9ea062d1f", "type": "subtopic", "title": "Legal foundations of schooling", "children": [{"id": "7e2f3f50-7520-446a-a8f7-cc3363fcf695", "type": "concept", "title": "Compulsory education and equal protection"}, {"id": "b84ebf04-9476-4b61-8666-3a7ff289321b", "type": "concept", "title": "Student speech, search, privacy, and discipline"}, {"id": "8cc53a0b-cd79-43c6-a1eb-1f084d7801f2", "type": "concept", "title": "Church-state questions in schools"}], "description": "Students learn how constitutional, statutory, and policy frameworks shape schools."}, {"id": "e18f00da-a717-49fd-ae83-0684654947c7", "type": "subtopic", "title": "Civil rights and inclusion", "children": [{"id": "24e23591-a6a0-439e-b726-59526992417b", "type": "concept", "title": "Title VI, Title IX, Section 504, ADA, and IDEA"}, {"id": "18bfa36c-2dc8-4f31-947f-041e9c1fd3d6", "type": "concept", "title": "English learner rights and language access"}, {"id": "9183b40f-cf99-4642-a293-3b10b3efc79e", "type": "concept", "title": "Harassment, bullying, and nondiscrimination"}], "description": "Students examine legal responsibilities for equitable access."}, {"id": "7cc4a027-4d93-4b2a-9413-dcd50e30e2c8", "type": "subtopic", "title": "Professional ethics and duty of care", "children": [{"id": "575522e3-88dd-4998-a0b9-b883787756fd", "type": "concept", "title": "Confidentiality and records"}, {"id": "033f41da-b6a6-42c8-90e7-bdd4a90bf724", "type": "concept", "title": "Mandated reporting"}, {"id": "3b238126-7a6c-4555-9ded-ad5e0a951152", "type": "concept", "title": "Boundaries, social media, and professional identity"}], "description": "Students learn norms of professional conduct and student protection."}]}, {"id": "65601c3b-b604-44e7-b9fe-50e1a83ed186", "type": "topic", "title": "Equity, Diversity, and Culturally Sustaining Education", "description": "Foundations of Education must center equity, not reserve it for an elective. This unit helps students connect social context to teaching practice and systems responsibility.", "children": [{"id": "212416df-5982-4489-8f4f-804c6b6390bd", "type": "subtopic", "title": "Equity frameworks", "children": [{"id": "04dee5aa-63a6-4d19-9b41-74d3edf62219", "type": "concept", "title": "Structural inequality and opportunity gaps"}, {"id": "62a20894-4241-4df3-8e50-cc593161ea0c", "type": "concept", "title": "Intersectionality and identity-safe environments"}, {"id": "4bd2b221-9c43-4b0a-9a26-cc2f6a56bb86", "type": "concept", "title": "Equity audits and disproportionality"}], "description": "Students learn to distinguish equal treatment from equitable opportunity."}, {"id": "9c892b4a-4893-42b6-942c-3a0b763c0bc7", "type": "subtopic", "title": "Culturally responsive and sustaining pedagogy", "children": [{"id": "50983b28-3023-4e34-aa53-20325cf759d6", "type": "concept", "title": "Culturally relevant pedagogy"}, {"id": "4ebd7e4d-9b92-4d32-a7a6-f9d28799702a", "type": "concept", "title": "Culturally responsive teaching"}, {"id": "91be8001-61c3-459e-8448-f815955da45b", "type": "concept", "title": "Culturally sustaining pedagogy and funds of knowledge"}], "description": "Students learn instructional approaches that affirm identity while supporting rigorous learning."}, {"id": "73a8f3be-a1b1-41d8-a59d-e1ad87e0a582", "type": "subtopic", "title": "Inclusive and anti-oppressive practice", "children": [{"id": "71d03eb5-e236-44eb-a3af-35750164a612", "type": "concept", "title": "Anti-bias and anti-racist teaching"}, {"id": "3050220f-31c8-41a2-ba38-a02fcc966534", "type": "concept", "title": "Multilingual learners and language assets"}, {"id": "3ccdf627-911b-4abd-aa3d-9f512e4ff929", "type": "concept", "title": "Disability justice, UDL, and accessibility"}], "description": "Students connect equity to classroom routines, curriculum, and family partnership."}]}, {"id": "eae7e6d3-301b-4cc1-8297-b873af9f8271", "type": "topic", "title": "Teacher Professionalism, Identity, and Reflective Practice", "description": "Teaching is intellectual, relational, ethical, and collaborative work. This unit helps students imagine themselves as reflective professionals inside a larger field.", "children": [{"id": "b5ef3553-1494-4b56-98d9-53a7a72ec4ec", "type": "subtopic", "title": "Teacher identity and professionalism", "