: "subtopic", "title": "Why compare education systems", "children": [{"id": "f7f80b72-0d99-4e15-ba2a-1f3c4b4a225d", "type": "concept", "title": "Policy borrowing and context"}, {"id": "6d776a17-1369-4219-90e1-c5f007cc27d0", "type": "concept", "title": "Culture, governance, and history"}, {"id": "14f3b3c4-4dc2-423c-87af-b1b312cbef34", "type": "concept", "title": "Limits of international rankings"}], "description": "Students learn what comparison can and cannot teach."}, {"id": "cf08115a-3dc9-4bab-a14e-e8d62b7b9d7b", "type": "subtopic", "title": "Global indicators and debates", "children": [{"id": "940b7c2a-7085-4bd7-ac0e-7d36f7f925e4", "type": "concept", "title": "PISA, TIMSS, and international assessments"}, {"id": "b4437469-139f-41df-9730-c7045b304ed8", "type": "concept", "title": "Access, literacy, gender, and development"}, {"id": "71133e8e-d443-4692-b241-33d1221f7107", "type": "concept", "title": "Human rights and education"}], "description": "Students examine common measures and their interpretation."}, {"id": "71a555a7-c445-418a-9249-796651532823", "type": "subtopic", "title": "Lessons for local practice", "children": [{"id": "afdc7e5d-66b5-48e3-bf2d-035cad8af3c1", "type": "concept", "title": "Teacher preparation and professional status"}, {"id": "d0f340e1-28b0-42dd-8ef0-a0509b5c281e", "type": "concept", "title": "Curriculum breadth and assessment culture"}, {"id": "5a55fa88-74ac-44bf-9e18-ea11ca3eab00", "type": "concept", "title": "Equity, inclusion, and multilingual education"}], "description": "Students connect global comparison to reflective professional judgment."}]}, {"id": "a4ee60ee-1961-4c74-b1b9-457812810054", "type": "topic", "title": "Current Debates, Reform, and the Future of Education", "description": "The capstone unit asks students to use history, philosophy, sociology, learning science, law, policy, and equity to analyze live debates in education.", "children": [{"id": "6dcf8622-aaf5-415d-9493-d4be112bee14", "type": "subtopic", "title": "Major reform debates", "children": [{"id": "7f4fe617-1195-4bb9-b6fe-7dd6822489b9", "type": "concept", "title": "School choice, charters, vouchers, and privatization"}, {"id": "82bf5f54-9cc8-4507-9948-c6dc688c07f1", "type": "concept", "title": "Testing and accountability reform"}, {"id": "658e9567-0a17-4f42-b851-e9f674c0ae43", "type": "concept", "title": "Teacher workforce, pay, preparation, and retention"}], "description": "Students learn to evaluate reforms by asking who benefits, who decides, and what evidence matters."}, {"id": "715c48b1-2d7c-4cf3-b372-1d826b01e5a8", "type": "subtopic", "title": "Technology and the future of learning", "children": [{"id": "a88dcbfd-cd78-4d84-b455-9f3320997f8d", "type": "concept", "title": "AI, tutoring systems, and adaptive learning"}, {"id": "bcd6ed27-671b-42b4-81ee-99efe3246d22", "type": "concept", "title": "Privacy, surveillance, and data ethics"}, {"id": "fb71f7f1-483a-478b-a770-1e8d25e2048f", "type": "concept", "title": "Digital equity and access"}], "description": "Students examine opportunities and risks in educational technology."}, {"id": "3c30b98b-416f-4815-bfcc-12ceffa29c7c", "type": "subtopic", "title": "Professional synthesis", "children": [{"id": "4528d945-5e42-4bf8-bfbf-66ea1a4d8be4", "type": "concept", "title": "Final philosophy revision"}, {"id": "97fa6435-1208-4aa7-851e-e18aa73ca29a", "type": "concept", "title": "Evidence-based commitments"}, {"id": "baa906f4-4ecf-44d6-891a-70712c3a4f9c", "type": "concept", "title": "Action plan for fieldwork and future learning"}], "description": "Students articulate a grounded philosophy of education and teaching."}]}], "dbBacked": true}$foedjson$::jsonb,
